80: // CreateVppLinkInRetryLoop creates new link to VPP and waits for VPP to be up and running (by using simple
81: // VPP API call). This process is retried in a loop and has a timeout limit.
82: func CreateVppLinkInRetryLoop(socket string, log *logrus.Entry, timeout time.Duration,
83: 	retry time.Duration) (vpp *vpplink.VppLink, err error) {
84: 	// Get an API connection, with a few retries to accommodate VPP startup time
85: 	maxRetry := int(math.Round(float64(timeout.Nanoseconds() / retry.Nanoseconds())))
86: 	for i := 0; i < maxRetry; i++ {
87: 		vpp, err = vpplink.NewVppLink(socket, log)
88: 		if err != nil {
89: 			if i < (maxRetry / 2) {
90: 				/* do not warn, it is probably fine */
91: 				log.Infof("Waiting for VPP... [%d/%d]", i, maxRetry)
92: 			} else {
93: 				log.Warnf("Waiting for VPP... [%d/%d] %v", i, maxRetry, err)
94: 			}
95: 			err = nil
96: 			time.Sleep(retry)
97: 		} else {
98: 			// Try a simple API message to verify everything is up and running
99: 			version, err := vpp.GetVPPVersion()
100: 			if err != nil {
101: 				log.Warnf("Try [%d/%d] broken vpplink: %v", i, maxRetry, err)
102: 				err = nil
103: 				time.Sleep(retry)
104: 			} else {
105: 				log.Infof("Connected to VPP version %s", version)
106: 				return vpp, nil
107: 			}
108: 		}
109: 	}
110: 	return nil, errors.Errorf("Cannot connect to VPP after 10 tries")
111: }
